-- Numbers each outbox event when it is written (T380; FR-077), generated by Prisma from
-- schema.prisma: the CRM keeps the update with the highest number, so an older change never
-- overwrites a newer one, whatever their start times or the order they are delivered in.
-- AlterTable
ALTER TABLE "OutboxEvent" ADD COLUMN     "sequence" BIGSERIAL NOT NULL;

-- CreateIndex
CREATE UNIQUE INDEX "OutboxEvent_sequence_key" ON "OutboxEvent"("sequence");
